        assert_eq!(foreign.declaration_count, 1);
        assert!(!foreign.incomplete);
        let missing = summarize(vec![declaration(
            Some("2025-01-01T00:00:00Z"),
            None,
            Some("GBP"),
        )]);
        assert_eq!(missing.amount, None);
        assert_eq!(missing.declaration_count, 1);
