        );
        assert!(year.includes(Some("2024-12-31T23:00:00-02:00".parse().unwrap())));
        assert!(!year.includes(None));
        assert!(!year.includes(Some("2025-12-31T23:00:00-02:00".parse().unwrap())));
    }
}

