//! Shared exact declared totals and current parliament boundary.
use super::entity_details::{
    CategoryTotal, DeclarationCategory, DeclaredGbpPeriodTotal, MemberCurrencyTotal,
    MemberDeclaration,
};
use std::collections::BTreeMap;

pub fn add_known(
    total: &mut Option<bigdecimal::BigDecimal>,
    amount: Option<&bigdecimal::BigDecimal>,
) {
    if let Some(amount) = amount {
        match total {
            Some(total) => *total += amount,
            None => *total = Some(amount.clone()),
        }
    }
}

#[derive(Default)]
pub struct PeriodAggregate {
    currencies: BTreeMap<String, MemberCurrencyTotal>,
    categories: BTreeMap<(String, DeclarationCategory, String), CategoryTotal>,
    declaration_count: usize,
    pub(crate) entry_count: usize,
    pub(crate) unknown_currency_count: usize,
}

impl PeriodAggregate {
    pub(crate) fn observe(&mut self, declaration: &MemberDeclaration) {
        self.declaration_count += 1;
        for entry in &declaration.entries {
            self.entry_count += 1;
            let Some(currency) = &entry.currency else {
                self.unknown_currency_count += 1;
                continue;
            };
            let group =
                self.currencies
                    .entry(currency.clone())
                    .or_insert_with(|| MemberCurrencyTotal {
                        currency: currency.clone(),
                        amount: None,
                        entry_count: 0,
                        unknown_amount_count: 0,
                        categories: Vec::new(),
                    });
            add_known(&mut group.amount, entry.amount.as_ref());
            group.entry_count += 1;
            group.unknown_amount_count += usize::from(entry.amount.is_none());
            let category = self
                .categories
                .entry((
                    currency.clone(),
                    declaration.category,
                    declaration.category_name.clone(),
                ))
                .or_insert_with(|| CategoryTotal {
                    category: declaration.category,
                    category_name: declaration.category_name.clone(),
                    amount: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                });
            add_known(&mut category.amount, entry.amount.as_ref());
            category.entry_count += 1;
            category.unknown_amount_count += usize::from(entry.amount.is_none());
        }
    }

    pub(crate) fn gbp_total(&self) -> DeclaredGbpPeriodTotal {
        let gbp = self.currencies.get("GBP");
        DeclaredGbpPeriodTotal {
            amount: gbp.and_then(|group| group.amount.clone()),
            declaration_count: self.declaration_count,
            incomplete: self.unknown_currency_count > 0
                || gbp.is_some_and(|group| group.unknown_amount_count > 0),
        }
    }

    pub(crate) fn finish(mut self) -> Vec<MemberCurrencyTotal> {
        for ((currency, _, _), category) in self.categories {
            if let Some(group) = self.currencies.get_mut(&currency) {
                group.categories.push(category);
            }
        }
        self.currencies.into_values().collect()
    }
}

#[derive(Clone, Copy)]
pub struct CurrentParliamentStart(chrono::DateTime<chrono::Utc>);
impl CurrentParliamentStart {
    pub(crate) const fn value(&self) -> chrono::DateTime<chrono::Utc> {
        self.0
    }
    pub(crate) fn new() -> Self {
        use chrono::TimeZone;
        Self(
            chrono::Utc
                .with_ymd_and_hms(2024, 7, 9, 0, 0, 0)
                .single()
                .expect("valid parliament start"),
        )
    }
    pub(crate) fn includes(&self, declaration: &MemberDeclaration) -> bool {
        declaration.registered_at.is_some_and(|date| date >= self.0)
    }
}
//! Exact current-term rankings use the same aggregate as member summaries.
//! Companies includes every canonical non-individual kind, including unclassified funders.
use crate::domain::{
    models::{
        declared_totals::{CurrentParliamentStart, PeriodAggregate},
        entity_details::DeclarationCategory,
        rankings::{Ranking, RankingDeclaration, Rankings},
    },
    repositories::rankings::{RankingsError, RankingsRepo},
};
use std::collections::BTreeMap;
/// Fixed current-term top-ten operation.
pub trait RankingsService: Clone + Send + Sync + 'static {
    /// Returns all four boards from one snapshot.
    fn rankings(&self) -> impl Future<Output = Result<Rankings, RankingsError>> + Send;
}
/// Rankings application service.
#[derive(Clone)]
pub struct Service<R> {
    repo: R,
}
impl<R> Service<R> {
    /// Creates a rankings service.
    pub const fn new(repo: R) -> Self {
        Self { repo }
    }
}
fn top<K: Ord, I>(groups: BTreeMap<K, (I, PeriodAggregate)>) -> Vec<Ranking<I>> {
    let mut rows: Vec<_> = groups
        .into_iter()
        .map(|(key, (identity, aggregate))| {
            (
                key,
                Ranking {
                    identity,
                    total: aggregate.gbp_total(),
                },
            )
        })
        .collect();
    rows.sort_by(|left, right| {
        right
            .1
            .total
            .amount
            .cmp(&left.1.total.amount)
            .then_with(|| left.0.cmp(&right.0))
    });
    rows.into_iter().take(10).map(|(_, row)| row).collect()
}
impl<R: RankingsRepo> RankingsService for Service<R> {
    async fn rankings(&self) -> Result<Rankings, RankingsError> {
        let boundary = CurrentParliamentStart::new();
        let sources = self.repo.ranking_declarations(boundary.value()).await?;
        Ok(summarize(sources, boundary))
    }
}
fn summarize(sources: Vec<RankingDeclaration>, boundary: CurrentParliamentStart) -> Rankings {
    let mut members = BTreeMap::new();
    let mut individuals = BTreeMap::new();
    let mut companies = BTreeMap::new();
    let mut parties = BTreeMap::new();
    for source in sources {
        let declaration = source.declaration;
        if !boundary.includes(&declaration) {
            continue;
        }
        members
            .entry(source.member.id.value())
            .or_insert_with(|| (source.member, PeriodAggregate::default()))
            .1
            .observe(&declaration);
        if declaration.category != DeclarationCategory::DonationSupport {
            continue;
        }
        let party = parties
            .entry(source.party.id)
            .or_insert_with(|| (source.party.clone(), PeriodAggregate::default()));
        if source.party.name < party.0.name {
            party.0.name = source.party.name;
        }
        party.1.observe(&declaration);
        let mut funders = BTreeMap::new();
        for entry in &declaration.entries {
            if let Some(funder) = entry
                .funder
                .as_ref()
                .and_then(|reference| source.funders.get(&reference.id.value()))
            {
                funders
                    .entry(funder.id.value())
                    .or_insert_with(|| (funder.clone(), Vec::new()))
                    .1
                    .push(entry.clone());
            }
        }
        for (key, (funder, entries)) in funders {
            let board = if funder.kind.is_individual() {
                &mut individuals
            } else {
                &mut companies
            };
            let mut projected = declaration.clone();
            projected.entries = entries;
            board
                .entry(key)
                .or_insert_with(|| (funder, PeriodAggregate::default()))
                .1
                .observe(&projected);
        }
    }
    Rankings {
        current_term_start: boundary.value(),
        members: top(members),
        individuals: top(individuals),
        companies: top(companies),
        parties: top(parties),
    }
}

